450	    private ResultActions load(String legId, int expectedVersion, List<String> bagTags) throws Exception {
451	        return postJson("/api/legs/" + legId + "/load", Map.of(
452	                "requestId", UUID.randomUUID().toString(),
453	                "expectedVersion", expectedVersion, "bagTags", bagTags));
454	    }
455	
456	    private ResultActions seal(String legId, int expectedVersion) throws Exception {
457	        return postJson("/api/legs/" + legId + "/seal", Map.of(
458	                "requestId", UUID.randomUUID().toString(), "expectedVersion", expectedVersion));
459	    }
460	
461	    private ResultActions arriveExact(String legId, List<String> bagTags) throws Exception {
462	        return postJson("/api/legs/" + legId + "/arrive", Map.of(
463	                "requestId", UUID.randomUUID().toString(), "bagTags", bagTags));
464	    }
